import heapq


def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs or k <= 0:
        return 0

    coords = sorted({t for s, e, _ in jobs for t in (s, e)})
    idx = {t: i for i, t in enumerate(coords)}
    m = len(coords)

    # Adjacency list: each edge is [to, cap, cost, rev_idx]
    adj: list[list[list[int]]] = [[] for _ in range(m)]

    def add_edge(u: int, v: int, cap: int, cost: int) -> None:
        adj[u].append([v, cap, cost, len(adj[v])])
        adj[v].append([u, 0, -cost, len(adj[u]) - 1])

    for i in range(m - 1):
        add_edge(i, i + 1, k, 0)

    for s, e, p in jobs:
        add_edge(idx[s], idx[e], 1, -p)

    INF = 10**18
    # Initial Johnson potentials via topological DP on the initial DAG
    pi = [INF] * m
    pi[0] = 0
    for u in range(m):
        pu = pi[u]
        if pu == INF:
            continue
        for v, cap, cost, _ in adj[u]:
            if cap > 0:
                nv = pu + cost
                if nv < pi[v]:
                    pi[v] = nv

    total_cost = 0
    sink = m - 1

    for _ in range(k):
        dist = [INF] * m
        dist[0] = 0
        parent_node = [-1] * m
        parent_edge = [-1] * m
        heap = [(0, 0)]

        while heap:
            d, u = heapq.heappop(heap)
            if d != dist[u]:
                continue
            pu = pi[u]
            for ei, (v, cap, cost, _) in enumerate(adj[u]):
                if cap > 0:
                    nd = d + cost + pu - pi[v]
                    if nd < dist[v]:
                        dist[v] = nd
                        parent_node[v] = u
                        parent_edge[v] = ei
                        heapq.heappush(heap, (nd, v))

        if dist[sink] == INF:
            break

        for i in range(m):
            if dist[i] < INF:
                pi[i] += dist[i]

        if pi[sink] >= 0:
            break

        total_cost += pi[sink]
        v = sink
        while v != 0:
            u = parent_node[v]
            ei = parent_edge[v]
            edge = adj[u][ei]
            edge[1] -= 1
            adj[v][edge[3]][1] += 1
            v = u

    return -total_cost
